"use client";

import { useEffect, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  TrashIcon as PhTrash,
  ArrowCounterClockwiseIcon as PhUndo,
  ArchiveIcon as PhArchive,
  LockSimpleIcon as PhLock,
  CheckIcon as PhCheck,
} from "@phosphor-icons/react";

type Phase = "idle" | "justDeleted" | "held" | "gone" | "restored";

const DURATIONS: Partial<Record<Phase, number>> = {
  justDeleted: 4000,
  held: 6000,
  restored: 1400,
};

const ANNOUNCE: Record<Phase, string> = {
  idle: "",
  justDeleted: "Deleted. Undo is available for a few seconds.",
  held: "Moved to Recently Deleted. Still restorable, but not for long.",
  gone: "Permanently deleted. This can no longer be recovered.",
  restored: "Restored.",
};

function TrashIcon() {
  return <PhTrash size={15} aria-hidden />;
}

function UndoIcon() {
  return <PhUndo size={13} aria-hidden />;
}

function ArchiveIcon() {
  return <PhArchive size={15} aria-hidden />;
}

function LockIcon() {
  return <PhLock size={15} aria-hidden />;
}

function CheckIcon() {
  return <PhCheck size={13} weight="bold" aria-hidden />;
}

interface UndoableActionProps {
  title?: string;
  subtitle?: string;
  undoWindowMs?: number;
  holdWindowMs?: number;
  onPermanentlyDeleted?: () => void;
  className?: string;
}

export function UndoableAction({
  title = "Q3 roadmap notes",
  subtitle = "Edited 2 hours ago",
  undoWindowMs = DURATIONS.justDeleted!,
  holdWindowMs = DURATIONS.held!,
  onPermanentlyDeleted,
  className,
}: UndoableActionProps) {
  const [phase, setPhase] = useState<Phase>("idle");
  const [remaining, setRemaining] = useState(0);
  const [restoredFrom, setRestoredFrom] = useState<"justDeleted" | "held" | null>(null);
  const shouldReduceMotion = useReducedMotion();
  const rafRef = useRef<number | null>(null);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const onPermanentlyDeletedRef = useRef(onPermanentlyDeleted);
  onPermanentlyDeletedRef.current = onPermanentlyDeleted;

  const windowFor: Partial<Record<Phase, number>> = {
    justDeleted: undoWindowMs,
    held: holdWindowMs,
    restored: DURATIONS.restored!,
  };

  useEffect(() => {
    const duration = windowFor[phase];
    if (!duration) {
      setRemaining(0);
      return;
    }
    const start = performance.now();
    setRemaining(duration);

    const tick = () => {
      const left = Math.max(0, duration - (performance.now() - start));
      setRemaining(left);
      if (left > 0) rafRef.current = requestAnimationFrame(tick);
    };
    rafRef.current = requestAnimationFrame(tick);

    timeoutRef.current = setTimeout(() => {
      setPhase((current) => {
        if (current === "justDeleted") return "held";
        if (current === "held") {
          onPermanentlyDeletedRef.current?.();
          return "gone";
        }
        if (current === "restored") return "idle";
        return current;
      });
    }, duration);

    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [phase]);

  const seconds = (remaining / 1000).toFixed(1);
  const progress = phase === "justDeleted" ? remaining / undoWindowMs : phase === "held" ? remaining / holdWindowMs : 0;

  const fade = shouldReduceMotion
    ? { initial: { opacity: 0 }, animate: { opacity: 1 }, exit: { opacity: 0 } }
    : { initial: { opacity: 0, y: -6 }, animate: { opacity: 1, y: 0 }, exit: { opacity: 0, y: 6 } };

  return (
    <div className={className}>
      <div
        role="group"
        aria-label={title}
        className="relative w-full overflow-hidden rounded-2xl border border-slate-200/70 bg-white/95 shadow-sm backdrop-blur-xl transition-[filter,opacity] duration-500 dark:border-white/10 dark:bg-neutral-950/80"
      >
        <span className="sr-only" role="status" aria-live="polite">
          {ANNOUNCE[phase]}
        </span>

        <AnimatePresence mode="wait" initial={false}>
          {phase === "idle" && (
            <motion.div key="idle" {...fade} transition={{ duration: 0.22, ease: [0.22, 1, 0.36, 1] }} className="flex items-center gap-3 p-4">
              <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-slate-500/10 text-slate-500 dark:bg-white/10 dark:text-slate-300">
                <ArchiveIcon />
              </span>
              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-medium text-slate-900 dark:text-white">{title}</p>
                <p className="text-xs text-slate-400 dark:text-slate-500">{subtitle}</p>
              </div>
              <button
                type="button"
                onClick={() => setPhase("justDeleted")}
                aria-label={`Delete ${title}`}
                className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg text-slate-400 transition-colors hover:bg-rose-500/10 hover:text-rose-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-rose-500 dark:hover:text-rose-400"
              >
                <TrashIcon />
              </button>
            </motion.div>
          )}

          {phase === "justDeleted" && (
            <motion.div key="justDeleted" {...fade} transition={{ duration: 0.22, ease: [0.22, 1, 0.36, 1] }} className="p-4">
              <div className="flex items-center gap-3">
                <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-rose-500/15 text-rose-600 dark:text-rose-400">
                  <TrashIcon />
                </span>
                <div className="min-w-0 flex-1">
                  <p className="truncate text-sm font-medium text-rose-700 dark:text-rose-300">Deleted &ldquo;{title}&rdquo;</p>
                  <p className="text-xs tabular-nums text-rose-500/80 dark:text-rose-400/70">Undo available for {seconds}s</p>
                </div>
                <button
                  type="button"
                  onClick={() => {
                    setRestoredFrom("justDeleted");
                    setPhase("restored");
                  }}
                  className="inline-flex shrink-0 items-center gap-1.5 rounded-lg bg-rose-600 px-3 py-1.5 text-sm font-medium text-white transition-colors hover:bg-rose-500 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-rose-600"
                >
                  <UndoIcon />
                  Undo
                </button>
              </div>
              <div className="mt-3 h-1 overflow-hidden rounded-full bg-rose-500/15">
                <motion.div
                  className="h-full rounded-full bg-rose-500"
                  style={{ transformOrigin: "left" }}
                  animate={{ scaleX: progress }}
                  transition={{ duration: 0 }}
                />
              </div>
            </motion.div>
          )}

          {phase === "held" && (
            <motion.div key="held" {...fade} transition={{ duration: 0.22, ease: [0.22, 1, 0.36, 1] }} className="border-t border-dashed border-amber-400/40 p-4">
              <div className="flex items-center gap-3">
                <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-amber-500/15 text-amber-600 dark:text-amber-400">
                  <ArchiveIcon />
                </span>
                <div className="min-w-0 flex-1">
                  <p className="truncate text-sm font-medium text-amber-700 dark:text-amber-300">In Recently Deleted</p>
                  <p className="text-xs tabular-nums text-amber-600/70 dark:text-amber-400/60">Restorable for {seconds}s more</p>
                </div>
                <button
                  type="button"
                  onClick={() => {
                    setRestoredFrom("held");
                    setPhase("restored");
                  }}
                  className="inline-flex shrink-0 items-center gap-1.5 rounded-lg border border-amber-400/50 px-3 py-1.5 text-sm font-medium text-amber-700 transition-colors hover:bg-amber-500/10 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-amber-500 dark:text-amber-300"
                >
                  <UndoIcon />
                  Restore
                </button>
              </div>
              <div className="mt-3 h-1 overflow-hidden rounded-full bg-amber-500/15">
                <motion.div
                  className="h-full rounded-full bg-amber-400"
                  style={{ transformOrigin: "left" }}
                  animate={{ scaleX: progress }}
                  transition={{ duration: 0 }}
                />
              </div>
            </motion.div>
          )}

          {phase === "gone" && (
            <motion.div key="gone" {...fade} transition={{ duration: 0.3, ease: [0.22, 1, 0.36, 1] }} className="flex items-center gap-3 p-4 grayscale">
              <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-slate-500/10 text-slate-400 dark:bg-white/5 dark:text-slate-500">
                <LockIcon />
              </span>
              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-medium text-slate-500 dark:text-slate-400">Permanently deleted</p>
                <p className="text-xs text-slate-400 dark:text-slate-500">This can no longer be recovered.</p>
              </div>
            </motion.div>
          )}

          {phase === "restored" && (
            <motion.div key="restored" {...fade} transition={{ duration: 0.25, ease: [0.22, 1, 0.36, 1] }} className="flex items-center gap-3 p-4">
              <span className="relative flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400">
                {!shouldReduceMotion && (
                  <motion.span
                    aria-hidden
                    className="absolute rounded-full border-2 border-emerald-400/60"
                    style={{ inset: -3 }}
                    initial={{ scale: 0.7, opacity: 0.9 }}
                    animate={{ scale: 1.7, opacity: 0 }}
                    transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1] }}
                  />
                )}
                <CheckIcon />
              </span>
              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-medium text-emerald-700 dark:text-emerald-300">
                  {restoredFrom === "held" ? "Restored from Recently Deleted" : "Restored"}
                </p>
                <p className="truncate text-xs text-slate-400 dark:text-slate-500">{title} is back.</p>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}
